Problem statement:
Sort integers.

The first line contains n (0 <= n <= 100000). The second line contains n integers; each fits in a
signed 32-bit int (-2147483648 .. 2147483647).

Print the n integers in non-decreasing order on one line, separated by single spaces, followed by a
newline. When n = 0 print just a newline. The solution must run in O(n log n) time.

Sample input:
5
3 1 4 1 5

Sample output:
1 1 3 4 5

Student file sort_bubble.c:
  1 | /* sort_bubble.c - reads n integers and prints them sorted (bubble sort). */
  2 | #include <stdio.h>
  3 | #include <stdlib.h>
  4 | 
  5 | /* Swaps two integers in place. */
  6 | static void swap(int *first, int *second)
  7 | {
  8 |     int temp = *first;
  9 |     *first = *second;
 10 |     *second = temp;
 11 | }
 12 | 
 13 | /* Sorts the array in ascending order; stops early once a pass makes no swap. */
 14 | static void bubble_sort(int *values, int count)
 15 | {
 16 |     for (int pass = 0; pass < count - 1; pass++) {
 17 |         int swapped = 0;
 18 |         for (int i = 0; i < count - 1 - pass; i++) {
 19 |             if (values[i] > values[i + 1]) {
 20 |                 swap(&values[i], &values[i + 1]);
 21 |                 swapped = 1;
 22 |             }
 23 |         }
 24 |         if (!swapped) {
 25 |             break;
 26 |         }
 27 |     }
 28 | }
 29 | 
 30 | int main(void)
 31 | {
 32 |     int count;
 33 | 
 34 |     if (scanf("%d", &count) != 1 || count < 0) {
 35 |         return 1;
 36 |     }
 37 |     int *values = malloc((count > 0 ? count : 1) * sizeof(int));
 38 |     if (values == NULL) {
 39 |         return 1;
 40 |     }
 41 |     for (int i = 0; i < count; i++) {
 42 |         if (scanf("%d", &values[i]) != 1) {
 43 |             free(values);
 44 |             return 1;
 45 |         }
 46 |     }
 47 |     bubble_sort(values, count);
 48 |     for (int i = 0; i < count; i++) {
 49 |         printf(i == 0 ? "%d" : " %d", values[i]);
 50 |     }
 51 |     printf("\n");
 52 |     free(values);
 53 |     return 0;
 54 | }
